package main

import (
	"os"

	"github.com/integrio-intropy/intropy-cli/internal/atrium"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/spf13/cobra"
)

// sys publish posts the system's topology to Atrium. The checks and the
// request live in internal/atrium.Publish; this file is flag plumbing.
type sysPublishFlags struct {
	system    string
	atriumURL string
}

var sysPublishFlagValues sysPublishFlags

var sysPublishCmd = &cobra.Command{
	Use:   "publish",
	Short: "Publish the system's topology to Atrium",
	Long: "Build the system host, run its graph verb, and post the topology to Atrium with the commit, the " +
		"repository, and README.md and RUNBOOK.md: the system's from its directory (or the repository root when it " +
		"has none there), and each component's from its directory. " +
		"HEAD must be pushed to the remote's default branch and the system's directory must be clean, because " +
		"Atrium shows the last topology it receives for a system. Publishing a commit Atrium already holds " +
		"changes nothing. The ingest token is read from INTROPY_ATRIUM_TOKEN.",
	Args: cobra.NoArgs,
	RunE: func(cmd *cobra.Command, args []string) error {
		cfg, err := config.Load()
		if err != nil {
			return err
		}
		url, err := cfg.Resolve(config.Flags{AtriumURL: sysPublishFlagValues.atriumURL}).RequireAtriumURL()
		if err != nil {
			return newUsageErrorf("%v", err)
		}
		ctx, cancel := commandContext(cmd)
		defer cancel()
		return atrium.Publish(ctx, atrium.Options{
			System:    sysPublishFlagValues.system,
			URL:       url,
			Token:     os.Getenv(config.EnvAtriumToken),
			UserAgent: userAgent(),
			Stderr:    cmd.ErrOrStderr(),
		})
	},
}

func init() {
	f := sysPublishCmd.Flags()
	f.StringVar(&sysPublishFlagValues.system, "system", "", flagUsageManifestSystem)
	f.StringVar(&sysPublishFlagValues.atriumURL, "atrium-url", "", flagUsageAtriumURL)
	sysCmd.AddCommand(sysPublishCmd)
}
