package atrium

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/gittest"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

const record = `{"apiVersion":"topology.intropy.io/v1","kind":"SystemTopology","system":"order-flow"}`

// workspace builds a pushed system repository: an origin, and a clone holding
// one system host with a README and RUNBOOK at its root.
func workspace(t *testing.T) string {
	t.Helper()
	origin := gittest.NewRepo(t, "main")
	gittest.Commit(t, origin, "RUNBOOK.md", "# Runbook\n", "runbook")
	if err := template.WriteScaffold(filepath.Join(origin, "order-flow", "system-host"),
		template.Scaffold{Role: template.RoleSystemHost, Values: map[string]any{"name": "order-flow"}}); err != nil {
		t.Fatal(err)
	}
	gittest.Run(t, origin, "add", ".")
	gittest.Run(t, origin, "commit", "--quiet", "-m", "host")

	clone := t.TempDir()
	gittest.Run(t, clone, "clone", "--quiet", origin, ".")
	// A local path is not a hosted remote; point origin's URL somewhere that
	// names an owner while fetches still go to the local origin.
	gittest.Run(t, clone, "config", "remote.origin.url", "git@github.com:acme/order-flow.git")
	gittest.Run(t, clone, "config", "url."+origin+".insteadOf", "git@github.com:acme/order-flow.git")
	return clone
}

func fakeGraph(t *testing.T) {
	t.Helper()
	prev := runGraphRecord
	runGraphRecord = func(_ context.Context, _ string) (*topology.Topology, []byte, error) {
		topo, err := topology.Decode(strings.NewReader(record))
		return topo, []byte(record), err
	}
	t.Cleanup(func() { runGraphRecord = prev })
}

// atrium is a stand-in ingest endpoint that records what it received.
type atrium struct {
	status int
	reply  string
	got    *ingestRequest
	auth   string
}

func (a *atrium) serve(t *testing.T) string {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.URL.Path != "/api/topologies" {
			t.Errorf("got %s %s", r.Method, r.URL.Path)
		}
		a.auth = r.Header.Get("Authorization")
		a.got = &ingestRequest{}
		if err := json.NewDecoder(r.Body).Decode(a.got); err != nil {
			t.Error(err)
		}
		w.WriteHeader(a.status)
		w.Write([]byte(a.reply))
	}))
	t.Cleanup(srv.Close)
	return srv.URL
}

func publish(t *testing.T, dir, url string) (string, error) {
	t.Helper()
	var stderr bytes.Buffer
	err := Publish(context.Background(), Options{SourceDir: dir, URL: url, Token: "secret", Stderr: &stderr})
	return stderr.String(), err
}

func TestPublishPostsTheRecordWithItsCommit(t *testing.T) {
	fakeGraph(t)
	dir := workspace(t)
	a := &atrium{status: http.StatusCreated}
	url := a.serve(t)

	stderr, err := publish(t, dir, url)
	if err != nil {
		t.Fatal(err)
	}
	if a.auth != "Bearer secret" {
		t.Errorf("Authorization = %q", a.auth)
	}
	if a.got.Repository != "acme/order-flow" || a.got.Ref != "refs/heads/main" || a.got.Commit != gittest.HEAD(t, dir) {
		t.Errorf("got repository %q, ref %q, commit %q", a.got.Repository, a.got.Ref, a.got.Commit)
	}
	if string(a.got.Document) != record {
		t.Errorf("document = %s, want the record as the host printed it", a.got.Document)
	}
	// No docs in the system's directory: the repository root's are the system's.
	if got := docSummary(a.got.Docs); got != "README.md:system,RUNBOOK.md:system" {
		t.Errorf("docs = %v", got)
	}
	if !strings.Contains(stderr, "published order-flow @ ") {
		t.Errorf("stderr = %q", stderr)
	}
}

func TestPublishAgainWithNewDocsSaysSo(t *testing.T) {
	fakeGraph(t)
	a := &atrium{status: http.StatusOK, reply: `{"system":"order-flow","created":false,"updated":true}`}
	stderr, err := publish(t, workspace(t), a.serve(t))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(stderr, "updated its topology and docs") {
		t.Errorf("stderr = %q", stderr)
	}
}

func TestPublishTwiceIsNotAnError(t *testing.T) {
	fakeGraph(t)
	a := &atrium{status: http.StatusOK}
	stderr, err := publish(t, workspace(t), a.serve(t))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(stderr, "is already published") {
		t.Errorf("stderr = %q", stderr)
	}
}

func TestPublishRefusesUncommittedChanges(t *testing.T) {
	fakeGraph(t)
	dir := workspace(t)
	gittest.WriteFile(t, filepath.Join(dir, "order-flow", "Program.cs"), "// wip\n")
	a := &atrium{status: http.StatusCreated}

	_, err := publish(t, dir, a.serve(t))
	if err == nil || !strings.Contains(err.Error(), "uncommitted changes") {
		t.Fatalf("err = %v", err)
	}
	if a.got != nil {
		t.Error("posted despite uncommitted changes")
	}
}

func TestPublishRefusesACommitNotOnTheDefaultBranch(t *testing.T) {
	fakeGraph(t)
	dir := workspace(t)
	gittest.Run(t, dir, "switch", "--quiet", "-c", "feature")
	gittest.Commit(t, dir, "order-flow/Program.cs", "// feature\n", "feature")
	a := &atrium{status: http.StatusCreated}

	_, err := publish(t, dir, a.serve(t))
	if err == nil || !strings.Contains(err.Error(), "is not on origin/main") {
		t.Fatalf("err = %v", err)
	}
	if a.got != nil {
		t.Error("posted a commit that is not on the default branch")
	}
}

func TestPublishReportsAtriumsReason(t *testing.T) {
	fakeGraph(t)
	a := &atrium{status: http.StatusUnauthorized, reply: `{"error":"a valid bearer token is required"}`}
	_, err := publish(t, workspace(t), a.serve(t))
	if err == nil {
		t.Fatal("want an error")
	}
	for _, want := range []string{"401", "a valid bearer token is required", "INTROPY_ATRIUM_TOKEN"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error %q should mention %q", err, want)
		}
	}
}

func TestPublishNeedsAToken(t *testing.T) {
	err := Publish(context.Background(), Options{URL: "http://atrium.example"})
	if err == nil || !strings.Contains(err.Error(), "INTROPY_ATRIUM_TOKEN") {
		t.Fatalf("err = %v", err)
	}
}

func TestRepositorySlug(t *testing.T) {
	for remote, want := range map[string]string{
		"git@github.com:acme/order-flow.git":       "acme/order-flow",
		"https://github.com/acme/order-flow":       "acme/order-flow",
		"https://github.com/acme/order-flow.git/":  "acme/order-flow",
		"ssh://git@github.com/acme/order-flow.git": "acme/order-flow",
	} {
		got, err := RepositorySlug(remote)
		if err != nil || got != want {
			t.Errorf("RepositorySlug(%q) = %q, %v; want %q", remote, got, err, want)
		}
	}
	if _, err := RepositorySlug("order-flow"); err == nil {
		t.Error("want an error for a remote without an owner")
	}
}

// docSummary is path:about[:component] per doc, in the order sent.
func docSummary(docs []doc) string {
	var out []string
	for _, d := range docs {
		s := d.Path + ":" + d.About
		if d.Component != "" {
			s += ":" + d.Component
		}
		out = append(out, s)
	}
	return strings.Join(out, ",")
}

func TestPublishSendsTheSystemsAndComponentsDocs(t *testing.T) {
	prev := runGraphRecord
	const withComponents = `{"apiVersion":"topology.intropy.io/v1","kind":"SystemTopology","system":"order-flow",
		"components":[{"name":"order-loader","kind":"loader"},{"name":"order-extractor","kind":"extractor"}]}`
	runGraphRecord = func(_ context.Context, _ string) (*topology.Topology, []byte, error) {
		topo, err := topology.Decode(strings.NewReader(withComponents))
		return topo, []byte(withComponents), err
	}
	t.Cleanup(func() { runGraphRecord = prev })

	dir := workspace(t)
	// The system's own README beside its host wins over the root's; its
	// runbook still comes from the root. order-loader has both, the extractor none.
	gittest.WriteFile(t, filepath.Join(dir, "order-flow", "README.md"), "# Order flow\n")
	gittest.WriteFile(t, filepath.Join(dir, "order-flow", "order-loader", "README.md"), "# Loader\n")
	gittest.WriteFile(t, filepath.Join(dir, "order-flow", "order-loader", "RUNBOOK.md"), "# Loader runbook\n")
	gittest.Run(t, dir, "add", ".")
	gittest.Run(t, dir, "commit", "--quiet", "-m", "docs")
	gittest.Run(t, dir, "push", "--quiet", "origin", "HEAD:main")

	a := &atrium{status: http.StatusCreated}
	if _, err := publish(t, dir, a.serve(t)); err != nil {
		t.Fatal(err)
	}
	want := "order-flow/README.md:system,RUNBOOK.md:system," +
		"order-flow/order-loader/README.md:component:order-loader,order-flow/order-loader/RUNBOOK.md:component:order-loader"
	if got := docSummary(a.got.Docs); got != want {
		t.Errorf("docs = %s\nwant   %s", got, want)
	}
	if a.got.Docs[0].Content != "# Order flow\n" {
		t.Errorf("system README = %q", a.got.Docs[0].Content)
	}
}
// Package atrium publishes a system's topology to Atrium, the customer's
// integration portal.
//
// Atrium shares no code with the CLI: the contract is its ingest endpoint and
// the topology record the system host's graph verb prints. The record is sent
// as the host printed it, so Atrium can read fields this CLI does not model.
package atrium

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"strings"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// docFiles are the files Atrium shows beside a system, and beside each of
// its components.
var docFiles = []string{"README.md", "RUNBOOK.md"}

// What a doc describes, as Atrium's ingest names it.
const (
	aboutSystem    = "system"
	aboutComponent = "component"
)

// requestTimeout bounds the ingest call. A topology is kilobytes; anything
// slower than this is a portal that is down, not one that is busy.
const requestTimeout = 30 * time.Second

// runGraphRecord is a seam so tests need no .NET SDK.
var runGraphRecord = topology.RunGraphRecord

// Options configures Publish.
type Options struct {
	// System selects the host when the workspace holds several.
	System string

	// SourceDir is the workspace to search for system hosts; defaults to the
	// working directory.
	SourceDir string

	// URL is Atrium's base URL and Token its ingest token.
	URL   string
	Token string

	Runner     command.Runner
	HTTPClient *http.Client
	UserAgent  string
	Stderr     io.Writer
}

// ingestRequest is the body of Atrium's POST /api/topologies.
type ingestRequest struct {
	Repository string          `json:"repository"`
	Commit     string          `json:"commit"`
	Ref        string          `json:"ref"`
	Document   json.RawMessage `json:"document"`
	Docs       []doc           `json:"docs,omitempty"`
}

type doc struct {
	// Path is relative to the repository's root, with forward slashes.
	Path    string `json:"path"`
	Content string `json:"content"`
	// About is aboutSystem, or aboutComponent with Component naming it.
	About     string `json:"about"`
	Component string `json:"component,omitempty"`
}

// Publish reads one system's topology and posts it to Atrium.
//
// Only a commit on the remote's default branch is published, with the
// system's directory clean. Atrium treats the last snapshot it receives as the
// system's current one, so a branch or a dirty tree would replace what the
// default branch declares.
func Publish(ctx context.Context, opts Options) error {
	if opts.Token == "" {
		return fmt.Errorf("no Atrium ingest token; set %s", config.EnvAtriumToken)
	}
	if opts.SourceDir == "" {
		opts.SourceDir = "."
	}
	if opts.Runner == nil {
		opts.Runner = git.DefaultRunner()
	}
	if opts.HTTPClient == nil {
		opts.HTTPClient = &http.Client{Timeout: requestTimeout}
	}

	hosts, warnings := template.ListSystemHosts(opts.SourceDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	host, err := deploy.SelectHost(hosts, opts.System, opts.SourceDir)
	if err != nil {
		return err
	}

	// The system directory, not the host: the components the topology
	// describes are the host's siblings.
	g := git.Client{Runner: opts.Runner, Dir: filepath.Dir(host.Path)}
	src, err := inspectSource(ctx, g)
	if err != nil {
		return err
	}

	fmt.Fprintf(opts.Stderr, "reading topology from %s (building first; this can take a minute)\n", host.Path)
	topo, record, err := runGraphRecord(ctx, host.Path)
	if err != nil {
		return fmt.Errorf("%s: %w", host.Path, err)
	}
	if opts.System != "" && topo.System != opts.System {
		fmt.Fprintf(opts.Stderr, "warning: the topology declares system %q, not %q\n", topo.System, opts.System)
	}

	components := make([]string, 0, len(topo.Components))
	for _, c := range topo.Components {
		components = append(components, c.Name)
	}
	docs, err := readDocs(src.root, filepath.Dir(host.Path), components)
	if err != nil {
		return err
	}

	saved, err := post(ctx, opts, ingestRequest{
		Repository: src.repository,
		Commit:     src.commit,
		Ref:        "refs/heads/" + src.branch,
		Document:   record,
		Docs:       docs,
	})
	if err != nil {
		return err
	}
	target := opts.URL
	if u, err := url.Parse(opts.URL); err == nil && u.Host != "" {
		target = u.Host
	}
	switch saved {
	case savedCreated:
		fmt.Fprintf(opts.Stderr, "published %s @ %s to %s\n", topo.System, git.ShortSHA(src.commit), target)
	case savedUpdated:
		fmt.Fprintf(opts.Stderr, "%s @ %s was already published to %s; updated its topology and docs\n", topo.System, git.ShortSHA(src.commit), target)
	default:
		fmt.Fprintf(opts.Stderr, "%s @ %s is already published to %s\n", topo.System, git.ShortSHA(src.commit), target)
	}
	return nil
}

// What Atrium did with a snapshot.
type saved int

const (
	savedCreated saved = iota
	// savedUpdated: a commit Atrium had, now with a different topology or
	// docs, as when this CLI reads more files than the one that published it.
	savedUpdated
	savedUnchanged
)

// sourceState is what the system's repository says about the commit to publish.
type sourceState struct {
	root       string
	repository string
	commit     string
	branch     string
}

func inspectSource(ctx context.Context, g git.Client) (sourceState, error) {
	var st sourceState
	var err error
	if st.root, err = g.TopLevel(ctx); err != nil {
		return st, err
	}
	dirty, err := g.Status(ctx, ".")
	if err != nil {
		return st, err
	}
	if len(dirty) > 0 {
		return st, fmt.Errorf("uncommitted changes in %s:\n  %s\ncommit and push them first, so the topology matches its commit",
			g.Dir, strings.Join(dirty, "\n  "))
	}
	if st.commit, err = g.HEAD(ctx); err != nil {
		return st, err
	}

	remoteURL, ok, err := g.RemoteURL(ctx, gitops.RemoteName)
	if err != nil {
		return st, err
	}
	if !ok {
		return st, fmt.Errorf("the repository has no %s remote; Atrium identifies a system's repository by it", gitops.RemoteName)
	}
	if st.repository, err = RepositorySlug(remoteURL); err != nil {
		return st, err
	}

	if st.branch, err = g.DefaultBranch(ctx, gitops.RemoteName); err != nil {
		return st, err
	}
	// Fetch first: a stale remote-tracking ref makes a pushed commit look unpushed.
	if err := g.Fetch(ctx, gitops.RemoteName, st.branch); err != nil {
		return st, err
	}
	remoteRef := gitops.RemoteName + "/" + st.branch
	onDefault, err := g.IsAncestor(ctx, st.commit, remoteRef)
	if err != nil {
		return st, err
	}
	if !onDefault {
		return st, fmt.Errorf("HEAD (%s) is not on %s\nAtrium shows the default branch; publish from a pushed commit on %s",
			git.ShortSHA(st.commit), remoteRef, st.branch)
	}
	return st, nil
}

// RepositorySlug reduces a git remote URL to owner/name, the form Atrium
// identifies a repository by. It accepts https, ssh and scp-style URLs.
func RepositorySlug(remote string) (string, error) {
	p := remote
	if strings.Contains(remote, "://") {
		u, err := url.Parse(remote)
		if err != nil {
			return "", fmt.Errorf("read remote URL %s: %w", remote, err)
		}
		p = u.Path
	} else if _, after, ok := strings.Cut(remote, ":"); ok {
		p = after
	}
	p = strings.TrimSuffix(strings.Trim(p, "/"), ".git")
	owner, name := path.Split(p)
	owner = path.Base(strings.TrimSuffix(owner, "/"))
	if name == "" || owner == "" || owner == "." || owner == "/" {
		return "", fmt.Errorf("remote URL %s does not name an owner and a repository", remote)
	}
	return owner + "/" + name, nil
}

// readDocs reads the README.md and RUNBOOK.md Atrium shows. The system's come
// from its directory (the host's parent), or the repository's root when the
// system has none there, so two systems in one repository each get their
// own. A component's come from its directory, the host's sibling named after
// it. Paths are sent relative to the root, so Atrium can link to the files.
func readDocs(root, systemDir string, components []string) ([]doc, error) {
	root, err := realPath(root)
	if err != nil {
		return nil, err
	}
	if systemDir, err = realPath(systemDir); err != nil {
		return nil, err
	}
	var docs []doc
	add := func(file, about, component string) (bool, error) {
		b, err := os.ReadFile(file)
		if errors.Is(err, os.ErrNotExist) {
			return false, nil
		}
		if err != nil {
			return false, fmt.Errorf("read %s: %w", file, err)
		}
		rel, err := filepath.Rel(root, file)
		if err != nil {
			return false, err
		}
		docs = append(docs, doc{Path: filepath.ToSlash(rel), Content: string(b), About: about, Component: component})
		return true, nil
	}
	for _, name := range docFiles {
		for _, dir := range []string{systemDir, root} {
			found, err := add(filepath.Join(dir, name), aboutSystem, "")
			if err != nil {
				return nil, err
			}
			if found {
				break
			}
		}
	}
	for _, c := range components {
		for _, name := range docFiles {
			if _, err := add(filepath.Join(systemDir, c, name), aboutComponent, c); err != nil {
				return nil, err
			}
		}
	}
	return docs, nil
}

// realPath is an absolute path with symlinks resolved, so paths under the
// git root (which git reports resolved) can be made relative to it.
func realPath(p string) (string, error) {
	abs, err := filepath.Abs(p)
	if err != nil {
		return "", err
	}
	return filepath.EvalSymlinks(abs)
}

// post sends the snapshot and reports what Atrium did with it. A snapshot
// Atrium already holds for the same system and commit is not an error:
// publishing twice is how a missed publish is retried, and how docs this CLI
// reads that an older one didn't reach Atrium.
func post(ctx context.Context, opts Options, body ingestRequest) (saved, error) {
	payload, err := json.Marshal(body)
	if err != nil {
		return savedUnchanged, err
	}
	endpoint := strings.TrimRight(opts.URL, "/") + "/api/topologies"
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(payload))
	if err != nil {
		return savedUnchanged, fmt.Errorf("publish to %s: %w", opts.URL, err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+opts.Token)
	if opts.UserAgent != "" {
		req.Header.Set("User-Agent", opts.UserAgent)
	}
	res, err := opts.HTTPClient.Do(req)
	if err != nil {
		return savedUnchanged, fmt.Errorf("publish to %s: %w", opts.URL, err)
	}
	defer res.Body.Close()

	reply, _ := io.ReadAll(io.LimitReader(res.Body, 4096))
	switch res.StatusCode {
	case http.StatusCreated:
		return savedCreated, nil
	case http.StatusOK:
		var r struct {
			Updated bool `json:"updated"`
		}
		if json.Unmarshal(reply, &r) == nil && r.Updated {
			return savedUpdated, nil
		}
		return savedUnchanged, nil
	}
	var e struct {
		Error string `json:"error"`
	}
	msg := strings.TrimSpace(string(reply))
	if json.Unmarshal(reply, &e) == nil && e.Error != "" {
		msg = e.Error
	}
	err = fmt.Errorf("atrium refused the topology: %s: %s", res.Status, msg)
	if res.StatusCode == http.StatusUnauthorized {
		err = fmt.Errorf("%w\ncheck %s", err, config.EnvAtriumToken)
	}
	return savedUnchanged, err
}
