// workspace builds a pushed system repository: an origin, and a clone holding
// one system host with a README and RUNBOOK at its root.
func workspace(t *testing.T) string {
	t.Helper()
	origin := gittest.NewRepo(t, "main")
	gittest.Commit(t, origin, "RUNBOOK.md", "# Runbook\n", "runbook")
	if err := template.WriteScaffold(filepath.Join(origin, "order-flow", "system-host"),
		template.Scaffold{Role: template.RoleSystemHost, Values: map[string]any{"name": "order-flow"}}); err != nil {
		t.Fatal(err)
	}
	gittest.Run(t, origin, "add", ".")
	gittest.Run(t, origin, "commit", "--quiet", "-m", "host")

	clone := t.TempDir()
	gittest.Run(t, clone, "clone", "--quiet", origin, ".")
	// A local path is not a hosted remote; point origin's URL somewhere that
	// names an owner while fetches still go to the local origin.
	gittest.Run(t, clone, "config", "remote.origin.url", "git@github.com:acme/order-flow.git")
	gittest.Run(t, clone, "config", "url."+origin+".insteadOf", "git@github.com:acme/order-flow.git")
	return clone
}

func fakeGraph(t *testing.T) {
	t.Helper()
	prev := runGraphRecord
	runGraphRecord = func(_ context.Context, _ string) (*topology.Topology, []byte, error) {
		topo, err := topology.Decode(strings.NewReader(record))
		return topo, []byte(record), err
	}
	t.Cleanup(func() { runGraphRecord = prev })
}

// atrium is a stand-in ingest endpoint that records what it received.
type atrium struct {
	status int
	reply  string
	got    *ingestRequest
	auth   string
}

func (a *atrium) serve(t *testing.T) string {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.URL.Path != "/api/topologies" {
			t.Errorf("got %s %s", r.Method, r.URL.Path)
		}
		a.auth = r.Header.Get("Authorization")
		a.got = &ingestRequest{}
		if err := json.NewDecoder(r.Body).Decode(a.got); err != nil {
			t.Error(err)
		}
		w.WriteHeader(a.status)
		w.Write([]byte(a.reply))
	}))
	t.Cleanup(srv.Close)
	return srv.URL
}

func publish(t *testing.T, dir, url string) (string, error) {
	t.Helper()
	var stderr bytes.Buffer
	err := Publish(context.Background(), Options{SourceDir: dir, URL: url, Token: "secret", Stderr: &stderr})
	return stderr.String(), err
}

func TestPublishPostsTheRecordWithItsCommit(t *testing.T) {
	fakeGraph(t)
	dir := workspace(t)
	a := &atrium{status: http.StatusCreated}
	url := a.serve(t)

	stderr, err := publish(t, dir, url)
	if err != nil {
		t.Fatal(err)
	}
	if a.auth != "Bearer secret" {
		t.Errorf("Authorization = %q", a.auth)
	}
	if a.got.Repository != "acme/order-flow" || a.got.Ref != "refs/heads/main" || a.got.Commit != gittest.HEAD(t, dir) {
		t.Errorf("got repository %q, ref %q, commit %q", a.got.Repository, a.got.Ref, a.got.Commit)
	}
	if string(a.got.Document) != record {
		t.Errorf("document = %s, want the record as the host printed it", a.got.Document)
	}
	// No docs in the system's directory: the repository root's are the system's.
	if got := docSummary(a.got.Docs); got != "README.md:system,RUNBOOK.md:system" {
		t.Errorf("docs = %v", got)
	}
	if !strings.Contains(stderr, "published order-flow @ ") {
		t.Errorf("stderr = %q", stderr)
	}
}

