// docSummary is path:about[:component] per doc, in the order sent.
func docSummary(docs []doc) string {
	var out []string
	for _, d := range docs {
		s := d.Path + ":" + d.About
		if d.Component != "" {
			s += ":" + d.Component
		}
		out = append(out, s)
	}
	return strings.Join(out, ",")
}

